SELECT page, DATE_TRUNC('MONTH', event_time) AS activity_month, STDDEV_SAMP(duration_sec) AS duration_sec_stddev, SIZE(COLLECT_SET(event_type)) AS num_event_types, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min, MAX(duration_sec) FILTER (WHERE event_type = 'purchase') AS purchase_max_duration_sec, PERCENTILE_APPROX(duration_sec, 0.95) AS duration_sec_p95 FROM web_events GROUP BY 1, 2 HAVING MAX(duration_sec) FILTER (WHERE event_type = 'purchase') > 0
